        private static readonly Dictionary<string, Shape> Parsed = new();

        public static bool TryGet(string name, out Shape shape)
        {
            if (Parsed.TryGetValue(name, out shape))
            {
                return true;
            }

            if (!Paths.TryGetValue(name, out var icon))
            {
                return false;
            }

            shape = new Shape(icon.Width, icon.Height, StreamGeometry.Parse(icon.Path));
            Parsed[name] = shape;
            return true;
        }
    }
